<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import MarketplaceLayout from '@/Layouts/MarketplaceLayout.vue';
import AppNotice from '@/Components/Product/AppNotice.vue';
const props = defineProps({ mode: String, valid: Boolean, done: Boolean, area: String, token: String });
const form = useForm({});
const submit = () => form.post(`/marketplace/launch-updates/${props.mode}/${props.token}`);
</script>
<template><Head title="Your area updates | Clipperdesk Marketplace"><meta name="robots" content="noindex, nofollow, noarchive"/><meta name="referrer" content="no-referrer"/></Head><MarketplaceLayout><main class="mp-container mp-narrow"><p class="mp-eyebrow">YOUR MARKETPLACE UPDATES</p><h1 class="mp-title">{{done ? mode==='confirm' ? 'You’re on the list.' : 'You’re unsubscribed.' : mode==='confirm' ? 'Something good, closer to you.' : 'Your inbox, your choice.'}}</h1><div class="mp-card"><AppNotice v-if="done" tone="success" :title="mode==='confirm' ? 'Your area updates are confirmed' : 'Your area updates are cancelled'" :description="mode==='confirm' ? 'We’ll email when businesses join your requested area. This signup is for an area-launch update, with no ongoing promotions.' : 'We won’t send you an area-launch update. Your account and booking messages are unchanged.'"/><template v-else-if="valid"><p class="mp-lead">{{mode==='confirm' ? `Confirm that you’d like an email when businesses join ${area}. Unsubscribe anytime.` : `Stop area-launch updates for ${area}?`}}</p><form class="mp-actions" @submit.prevent="submit"><button class="mp-button" :disabled="form.processing">{{form.processing ? 'Saving…' : mode==='confirm' ? 'Confirm updates' : 'Unsubscribe'}}</button><Link href="/marketplace" class="mp-button secondary">Back to Marketplace</Link></form></template><AppNotice v-else title="This link is no longer available" description="Your account and bookings are unchanged. You can request a new area update from Marketplace."><template #actions><a href="/marketplace#area-updates" class="mp-button">Choose my area</a></template></AppNotice><div v-if="done" class="mp-actions"><Link href="/marketplace" class="mp-button">Explore Marketplace</Link></div></div></main></MarketplaceLayout></template>
